import permutationsHeap from '../../src/permutations_heap.js';

describe('permutationsHeap', () => {
  test('generates all permutations for [1, 2, 3] using Heap algorithm', () => {
    const input = [1, 2, 3];
    const original = input.slice();
    const result = permutationsHeap(input);
    expect(Array.isArray(result)).toBe(true);
    expect(result.length).toBe(6);

    // Ensure all permutations are unique
    const serialized = result.map(p => JSON.stringify(p));
    expect(new Set(serialized).size).toBe(6);

    // Ensure each permutation contains the same elements as input
    const sortedOriginal = original.slice().sort();
    result.forEach(p => {
      expect(Array.isArray(p)).toBe(true);
      expect(p.length).toBe(original.length);
      const sortedPerm = p.slice().sort();
      expect(sortedPerm).toEqual(sortedOriginal);
    });

    // Original input elements should still be the same set (order may have changed)
    expect(input.slice().sort()).toEqual(sortedOriginal);
  });

  test('returns a single permutation for empty array', () => {
    const input = [];
    const result = permutationsHeap(input);
    expect(Array.isArray(result)).toBe(true);
    // Expecting one permutation: the empty array
    expect(result.length).toBe(1);
    expect(result[0]).toEqual([]);
  });

  test('throws TypeError when input is not an array', () => {
    expect(() => permutationsHeap(null)).toThrow(TypeError);
    expect(() => permutationsHeap(undefined)).toThrow(TypeError);
    expect(() => permutationsHeap(123)).toThrow(TypeError);
    expect(() => permutationsHeap({})).toThrow(TypeError);
  });

  test('handles array of strings and does not assume immutability of input order', () => {
    const input = ['a', 'b', 'c'];
    const original = input.slice();
    const result = permutationsHeap(input);
    expect(result.length).toBe(6);

    // Ensure all permutations are unique
    const serialized = result.map(p => p.join(''));
    expect(new Set(serialized).size).toBe(6);

    // Each permutation should be a permutation of the original elements
    result.forEach(p => {
      expect(p.slice().sort()).toEqual(original.slice().sort());
    });

    // Original input elements should still be the same set (order may have changed)
    expect(input.slice().sort()).toEqual(original.slice().sort());
  });
});

