  test('returns an array of probabilities for positive lambda and sums to ~1', () => {
    const lambda = 1.0;
    const probs = poissonDistribution(lambda);
    expect(Array.isArray(probs)).toBe(true);
    expect(probs.length).toBeGreaterThan(5);
    const sum = probs.reduce((a, b) => a + b, 0);
    expect(sum).toBeCloseTo(1, 3);

    const factorial = (n) => {
      let f = 1;
      for (let i = 2; i <= n; i++) f *= i;
      return f;
    };

    for (let k = 0; k < 6; k++) {
      const expected = Math.exp(-lambda) * Math.pow(lambda, k) / factorial(k);
      expect(probs[k]).toBeCloseTo(expected, 6);
    }
  });

  test('returns undefined for non-positive lambda', () => {
    expect(poissonDistribution(0)).toBeUndefined();
    expect(poissonDistribution(-1)).toBeUndefined();
  });

  test('sum of probabilities is ~1 for moderate lambda (e.g., 4)', () => {
    const lambda = 4;
    const probs = poissonDistribution(lambda);
    const sum = probs.reduce((a, b) => a + b, 0);
    expect(sum).toBeCloseTo(1, 3);
    expect(probs.length).toBeGreaterThan(3);
  });

